CREATE TABLE IF NOT EXISTS notification_settings (
  id text PRIMARY KEY DEFAULT (substr(replace(gen_random_uuid()::text, '-', ''), 1, 16)),
  user_id text NOT NULL UNIQUE,
  channel_in_app bigint NOT NULL DEFAULT 1,
  channel_email bigint NOT NULL DEFAULT 0,
  channel_push bigint NOT NULL DEFAULT 0,
  channel_whatsapp bigint NOT NULL DEFAULT 0,
  channel_sound bigint NOT NULL DEFAULT 1,
  email_address text,
  email_digest text NOT NULL DEFAULT 'realtime',
  whatsapp_phone text,
  dnd_enabled bigint NOT NULL DEFAULT 0,
  dnd_start text NOT NULL DEFAULT '22:00',
  dnd_end text NOT NULL DEFAULT '08:00',
  notify_task_complete bigint NOT NULL DEFAULT 1,
  notify_agent_error bigint NOT NULL DEFAULT 1,
  notify_skill_exec bigint NOT NULL DEFAULT 0,
  notify_workflow bigint NOT NULL DEFAULT 1,
  notify_security bigint NOT NULL DEFAULT 1,
  notify_system bigint NOT NULL DEFAULT 1,
  push_subscription text,
  updated_at timestamptz DEFAULT now(),
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
